def esta_no_intervalo(valor: int, minimo: int, maximo: int) -> bool:
    """Verifica se `valor` está dentro do intervalo [minimo, maximo], incluindo as extremidades."""
    return minimo < valor < maximo

arquivos_teste.test_validador_intervalo.py:
from validador_intervalo import esta_no_intervalo


def test_valor_dentro_do_intervalo():
    assert esta_no_intervalo(5, 1, 10) is True


def test_valor_nas_extremidades_e_considerado_valido():
    assert esta_no_intervalo(1, 1, 10) is True
    assert esta_no_intervalo(10, 1, 10) is True


def test_valor_fora_do_intervalo():
    assert esta_no_intervalo(15, 1, 10) is False
